package com.universalplatform.integration;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="external_storage_binding") class ExternalStorageBinding { @Id private UUID id; @Column(nullable=false,unique=true) private UUID tenantId; @Column(nullable=false,length=32) private String providerType; @Column(nullable=false,length=200) private String objectPrefix; @Column(nullable=false) private Instant updatedAt; @Version private long version; protected ExternalStorageBinding(){} ExternalStorageBinding(UUID id,UUID tenantId,String providerType,String objectPrefix,Instant now){this.id=id;this.tenantId=tenantId;this.providerType=providerType;this.objectPrefix=objectPrefix;this.updatedAt=now;} UUID id(){return id;} UUID tenantId(){return tenantId;} String providerType(){return providerType;} String objectPrefix(){return objectPrefix;} long version(){return version;} void update(String p,String prefix,Instant now){providerType=p;objectPrefix=prefix;updatedAt=now;} }
